<         }
< 
<         if (line.startsWith('> ')) {
<             closeParagraph();
<             closeList();
<             quote.push(line.slice(2).trim());
<             return;
<         }
< 
<         closeQuote();
<         closeList();
<         paragraph.push(line);
<     });
< 
<     closeParagraph();
<     closeQuote();
<     closeList();
< 
<     return html.join('\n');
