< function parseJsonFromText(text = '') {
<     const trimmed = text.trim();
<     const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
<     const jsonText = fenced ? fenced[1] : trimmed;
< 
<     try {
<         return JSON.parse(jsonText);
<     } catch (error) {
<         const objectMatch = jsonText.match(/\{[\s\S]*\}/);
<         if (objectMatch) {
<             try {
<                 return JSON.parse(objectMatch[0]);
<             } catch (nestedError) {
<                 return parseLooseBlogDraft(objectMatch[0]);
<             }
<         }
< 
<         return parseLooseBlogDraft(jsonText);
<     }
< }
< 
< function parseLooseBlogDraft(text = '') {
<     function getStringField(key) {
<         const fieldStart = text.search(new RegExp(`"${key}"\\s*:`));
<         if (fieldStart < 0) return '';
< 
<         const valueStart = text.indexOf('"', text.indexOf(':', fieldStart) + 1);
<         if (valueStart < 0) return '';
< 
<         const remaining = text.slice(valueStart + 1);
<         const nextField = remaining.search(/",\s*"[a-zA-Z_][^"]*"\s*:/);
< 
<         if (nextField >= 0) {
<             return remaining.slice(0, nextField);
<         }
< 
<         return remaining
<             .replace(/"\s*[,}]?\s*$/, '')
<             .trim();
<     }
< 
<     function getTags() {
<         const tagMatch = text.match(/"tags"\s*:\s*\[([\s\S]*?)\]/);
<         if (!tagMatch) return [];
< 
<         return tagMatch[1]
<             .split(',')
<             .map((tag) => tag.replace(/["']/g, '').trim())
<             .filter(Boolean);
<     }
< 
<     function getPriority() {
<         const priorityMatch = text.match(/"priority"\s*:\s*(\d+)/);
<         return priorityMatch ? Number(priorityMatch[1]) : 99;
<     }
< 
<     const draft = {
<         title: getStringField('title'),
<         slug: getStringField('slug'),
<         tags: getTags(),
<         priority: getPriority(),
<         excerpt: getStringField('excerpt'),
<         body: getStringField('body')
<     };
< 
<     if (!draft.title || !draft.body) {
<         throw new Error('Unable to parse AI blog draft. Please try generating again.');
<     }
< 
<     return draft;
< }
