const fetch = require('node-fetch');

module.exports = function registerGoogleReviews(app) {
    let windowStart = Date.now();
    let requests = 0;
    app.get('/api/google-reviews', async (req, res) => {
        res.set('Cache-Control', 'no-store');
        const key = process.env.GOOGLE_PLACES_API_KEY;
        const placeId = process.env.GOOGLE_PLACE_ID;
        if (!key || !placeId) return res.status(503).json({ status: 'not_configured' });
        if (Date.now() - windowStart > 60000) { windowStart = Date.now(); requests = 0; }
        if (++requests > 30) return res.status(429).json({ status: 'try_later' });
        try {
            const response = await fetch(`https://places.googleapis.com/v1/places/${encodeURIComponent(placeId)}`, {
                timeout: 10000,
                headers: { 'X-Goog-Api-Key': key, 'X-Goog-FieldMask': 'rating,userRatingCount,reviews,googleMapsUri,attributions' }
            });
            if (!response.ok) throw new Error('Google reviews unavailable');
            const place = await response.json();
            res.json({ status: 'ok', rating: place.rating, count: place.userRatingCount, reviews: place.reviews || [], attributions: place.attributions || [] });
        } catch {
            res.status(502).json({ status: 'unavailable' });
        }
    });
};
